sys_script.script:
(function discrepancyLifecycle() {
    // Only process status changes
    if (!current.status.changes()) {
        gs.debug('[Retail Store Assistant] Discrepancy Lifecycle: no status change for discrepancy ' + current.getValue('discrepancy_number'));
        return;
    }

    var oldStatus = previous.getValue('status');
    var newStatus = current.getValue('status');
    var discNumber = current.getValue('discrepancy_number');

    gs.info('[Retail Store Assistant] Discrepancy Lifecycle: processing transition "' + oldStatus + '" → "' + newStatus + '" for discrepancy ' + discNumber);

    // Define valid transitions (V2.8: New → Under Investigation → Resolved → Closed)
    var validTransitions = {
        'new': ['under_investigation'],
        'under_investigation': ['resolved'],
        'resolved': ['closed'],
        'closed': []
    };

    var allowed = validTransitions[oldStatus] || [];
    var isValid = false;
    for (var i = 0; i < allowed.length; i++) {
        if (allowed[i] === newStatus) {
            isValid = true;
            break;
        }
    }

    if (!isValid) {
        gs.error('[Retail Store Assistant] Discrepancy Lifecycle: invalid transition "' + oldStatus + '" → "' + newStatus + '" for discrepancy ' + discNumber);
        gs.addErrorMessage('Discrepancy lifecycle violation: cannot transition from "' + oldStatus + '" to "' + newStatus + '".');
        current.setAbortAction(true);
        return;
    }

    // CRITICAL: Do NOT modify Inventory Position
    // CRITICAL: Do NOT create an Inventory Transaction
    // The correction path is: Discrepancy → Investigation → Adjustment Request → Inventory Transaction

    gs.info('[Retail Store Assistant] Discrepancy Lifecycle: discrepancy ' + discNumber + ' transitioned to "' + newStatus + '"');
})();
